<template>
  <div class="upload-file">
    <el-upload
      action=""
      multiple
      :before-upload="handleBeforeUpload"
      :file-list="fileList"
      :limit="limit"
      :show-file-list="false"
      class="upload-file-uploader"
      ref="lease"
      :http-request="changeFile"
    >
      <!-- 上传按钮 -->
      <el-button
        size="mini"
        type="text"
        v-if="limit > fileList.length"
      >上传文件</el-button>
      <transition-group
        v-else
        class="upload-file-list el-upload-list el-upload-list--text"
        name="el-fade-in-linear"
        tag="ul"
      >
        <li
          :key="file.uid"
          class="el-upload-list__item ele-upload-list__item-content"
          v-for="(file, index) in fileList"
        >
          <span class="el-icon-document">
            {{ file.name }}
          </span>
          <div
            class="ele-upload-list__item-content-action"
            style="margin-left: 5px"
          >
            <el-link
              :underline="false"
              @click.stop="handleDeleteFile(index)"
              type="danger"
            >删除</el-link>
          </div>
        </li>
      </transition-group>
      <!-- 上传提示 -->
      <div
        class="el-upload__tip"
        slot="tip"
        v-if="showTip"
      >
        请上传
        <!-- <template v-if="fileSize">
          大小不超过
          <b style="color: #f56c6c">{{ fileSize }}MB</b></template
        >  -->
        <template v-if="fileType">
          格式为 <b style="color: #f56c6c">{{ fileType.join("/") }}</b>
        </template>
        的文件
      </div>
    </el-upload>

    <!-- 文件列表 -->
  </div>
</template>

<script>
export default {
  props: {
    file: {
      type: Array,
      default: () => []
    },
    fileType: {
      type: Array,
      default: () => ["rknn", "rkllm"]
    }
  },
  data() {
    return {
      fileList: [],
      fileName: "",
      number: 0,
      headers: {
        Authorization: "Bearer " + localStorage.getItem("token")
      },
      uploadList: [],
      fileSize: 20,
      isShowTip: true,
      limit: 1
    };
  },
  computed: {
    // 是否显示提示
    showTip() {
      return this.fileType;
    }
  },
  created() {
    this.fileList = [...this.file];
  },
  watch: {
    file: {
      handler(val) {
        this.fileList = [...val];
      },
      deep: true,
      immediate: true
    }
  },
  methods: {
    changeFile(data) {
      this.$emit("setFileName", data.file.name);
      this.fileList.push(data.file);
      console.log(this.fileList);
    },
    // 上传前校检格式和大小
    handleBeforeUpload(file) {
      // 校检文件类型
      if (this.fileType) {
        let fileExtension = "";
        if (file.name.lastIndexOf(".") > -1) {
          fileExtension = file.name.slice(file.name.lastIndexOf(".") + 1);
        }
        const isTypeOk = this.fileType.some(type => {
          if (file.type.indexOf(type) > -1) return true;
          if (fileExtension && fileExtension.indexOf(type) > -1) return true;
          return false;
        });
        if (!isTypeOk) {
          this.$modal.msgError(
            `文件格式不正确, 请上传${this.fileType.join("/")}格式文件!`
          );
          return false;
        }
      }
      // 校检文件大小
      // if (this.fileSize) {
      //   const isLt = file.size / 1024 / 1024 < this.fileSize;
      //   if (!isLt) {
      //     this.$modal.msgError(`上传文件大小不能超过 ${this.fileSize} MB!`);
      //     return false;
      //   }
      // }
      this.number++;
      return true;
    },
    // 删除文件
    handleDeleteFile(index) {
      this.fileList.splice(index, 1);
      this.$emit("input", this.listToString(this.fileList));
      this.$emit("setFileName", null);
    },
    // 获取文件名称
    getFileName(name) {
      if (name.lastIndexOf("/") > -1) {
        return name.slice(name.lastIndexOf("/") + 1);
      } else {
        return "";
      }
    },
    // 对象转成指定字符串分隔
    listToString(list, separator) {
      let strs = "";
      separator = separator || ",";
      for (let i in list) {
        strs += list[i].url + separator;
      }
      return strs != "" ? strs.substr(0, strs.length - 1) : "";
    }
  }
};
</script>

<style lang="scss" scoped>
.el-upload-list__item {
  display: flex;
  align-items: center;
}
</style>
